query:
SELECT DISTINCT ?root ?item ?en ?zh ?description ?kind WHERE {
      hint:Query hint:optimizer "None".
      { SELECT DISTINCT ?root ?item ?en ?zh WHERE {
        { VALUES ?root { wd:Q2326800 wd:Q994399 wd:Q25098928 wd:Q45045 wd:Q7524253 wd:Q4166054 wd:Q420904 wd:Q20877954 wd:Q93723795 wd:Q7534803 wd:Q3258688 wd:Q4459369 wd:Q2664496 wd:Q10567583 wd:Q7543545 wd:Q2295009 wd:Q4139327 wd:Q78338964 wd:Q17103391 wd:Q775963 } ?item wdt:P31 ?root }
        UNION { VALUES ?root { wd:Q2326800 wd:Q994399 wd:Q25098928 wd:Q45045 wd:Q7524253 wd:Q4166054 wd:Q420904 wd:Q20877954 wd:Q93723795 wd:Q7534803 wd:Q3258688 wd:Q4459369 wd:Q2664496 wd:Q10567583 wd:Q7543545 wd:Q2295009 wd:Q4139327 wd:Q78338964 wd:Q17103391 wd:Q775963 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q2326800 wd:Q994399 wd:Q25098928 wd:Q45045 wd:Q7524253 wd:Q4166054 wd:Q420904 wd:Q20877954 wd:Q93723795 wd:Q7534803 wd:Q3258688 wd:Q4459369 wd:Q2664496 wd:Q10567583 wd:Q7543545 wd:Q2295009 wd:Q4139327 wd:Q78338964 wd:Q17103391 wd:Q775963 } BIND(?root AS ?item) }
        ?item rdfs:label ?en, ?zh.
        FILTER(LANG(?en)="en" && LANG(?zh) IN ("zh-hans", "zh-cn", "zh", "zh-tw", "zh-hant"))
        FILTER NOT EXISTS { ?item wdt:P31 wd:Q5 }
      } LIMIT 20000 }
      OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
      OPTIONAL { ?item wdt:P31 ?kind }
    }
